    for k, v in d.items():
        if "%" in re.sub(r"%%|%\d", "", v): print("BARE %", k)
    os.makedirs(os.path.dirname(DST % lang), exist_ok=True)
    open(DST % lang, "w", encoding="utf-8").write(json.dumps(d, indent=4, ensure_ascii=False) + "\n")
    print(lang, len(d), "keys")
